  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content" class="app-shell">
      <div id="quiz-root"></div>
    </main>

    <script>
      const quizQuestions = [
        {
          id: "language-types",
          prompt: "Which of these are programming languages?",
          helpText: "Select every option that is a language people use to write software.",
          choices: ["Python", "HTML", "JavaScript", "JPEG"],
        },
        {
          id: "compiled-languages",
          prompt: "Which languages are commonly compiled before execution?",
          choices: ["C", "Rust", "Swift", "CSS"],
        },
        {
          id: "web-languages",
          prompt: "Which languages are used directly in web browsers?",
          choices: ["JavaScript", "HTML", "CSS", "SQL"],
        },
      ];

      function Choice({ questionId, choice }) {
        const inputId = `${questionId}-${choice.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

        return `
          <label class="choice" for="${inputId}">
            <input id="${inputId}" type="checkbox" name="${questionId}" value="${choice}">
            <span>${choice}</span>
          </label>
        `;
      }

      function QuestionField({ question, index }) {
        const helpId = `${question.id}-help`;
        const describedBy = question.helpText ? ` aria-describedby="${helpId}"` : "";

        return `
          <div class="form-field">
            <fieldset${describedBy}>
              <legend>${index + 1}. ${question.prompt}</legend>
              ${
                question.helpText
                  ? `<p id="${helpId}" class="help-text">${question.helpText}</p>`
                  : ""
              }
              <div class="choices">
                ${question.choices.map((choice) => Choice({ questionId: question.id, choice })).join("")}
              </div>
            </fieldset>
          </div>
        `;
      }

      function QuizApp({ questions }) {
        return `
          <section class="hero" aria-labelledby="quiz-title">
            <p class="eyebrow">Multi-select quiz</p>
            <h1 id="quiz-title">Computer Languages Quiz</h1>
            <p class="intro">Choose all answers that apply for each question, then submit your responses.</p>
          </section>
          <section class="quiz-card" aria-label="Quiz form">
            <form id="quiz-form" novalidate>
              ${questions.map((question, index) => QuestionField({ question, index })).join("")}
              <div class="actions">
                <button type="submit">Submit quiz</button>
                <p id="quiz-status" class="status" aria-live="polite"></p>
              </div>
            </form>
          </section>
        `;
      }

      document.getElementById("quiz-root").innerHTML = QuizApp({ questions: quizQuestions });

      document.getElementById("quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();

        const unansweredQuestion = quizQuestions.find(
          (question) => !document.querySelector(`input[name="${question.id}"]:checked`)
        );
        const status = document.getElementById("quiz-status");

        if (unansweredQuestion) {
          status.textContent = "Error: Select at least one answer for each question.";
          status.className = "status error";
          document.querySelector(`input[name="${unansweredQuestion.id}"]`).focus();
          return;
        }

        status.textContent = "Quiz submitted. Thanks for sharing your answers.";
        status.className = "status success";
      });
    </script>
  </body>
</html>
